import numpy as np
from scipy.optimize import curve_fit
d = np.genfromtxt('/app/spectrum.csv', delimiter=',', names=True)
x = d['raman_shift_cm1']; y = d['intensity']

def lor(x, x0, gamma, amp, off):
    return amp*gamma**2/((x-x0)**2+gamma**2)+off

def fit(lo, hi, p0):
    m = (x>=lo)&(x<=hi)
    xi, yi = x[m], y[m]
    p, cov = curve_fit(lor, xi, yi, p0=p0, maxfev=200000)
    r = yi-lor(xi,*p)
    return p, np.sqrt(np.mean(r**2)), len(xi)

peaks = {
 'D': [(1200,1480),(1250,1450),(1280,1420),(1300,1400)],
 'G': [(1480,1750),(1500,1700),(1530,1650),(1550,1620)],
 '2D':[(2500,2900),(2580,2800),(2600,2780),(2630,2760)],
}
p0 = {'D':(1345,25,2400,1000),'G':(1582,30,7900,1000),'2D':(2693,30,16000,1100)}
for name, wins in peaks.items():
    for w in wins:
        try:
            p, rms, n = fit(w[0], w[1], p0[name])
            print(f'{name} win {w}: x0={p[0]:.3f} gamma={p[1]:.3f} amp={p[2]:.2f} off={p[3]:.2f} rms={rms:.2f} n={n}')
        except Exception as e:
            print(name, w, 'FAIL', e)
    print()
